import type { Opportunity } from "@/data/opportunities";

/**
 * HSO catalogue update, September 2026. Everything in one file.
 *
 *  - hsoAdditionsSep2026: 1468 new U.S. high school listings, each checked on the official
 *    programme page (Sept 15: 331 from a directory sweep and the research sheet;
 *    Sept 16-19: 416 contests, scholarships, research placements, internships and
 *    university programmes; Sept 21: 332 more and Sept 22: 389 more,
 *    most of them the state-by-state
 *    programmes every student can reach - Boys and Girls State, the JSHS regional
 *    research symposia, HOBY seminars, state FFA associations and state scholarships -
 *    plus national programmes, so that no state is left with only a handful of listings).
 *  - hsoDeadlineReviewSep2026: 661 existing listings reviewed against their official pages:
 *    next-cycle deadlines and opening dates, past-cycle dates cleared to "Deadline TBA",
 *    dead links replaced, and 37 listings removed (ended, not open to high schoolers,
 *    or duplicates). Every row carries the quote it rests on in `evidence`. Rows marked
 *    `verified` were checked by hand where the automated link check was blocked; they clear
 *    the review flag so those listings are indexed and ranked normally.
 *
 * Wired into src/data/opportunities.ts in four places: the import, the
 * `...hsoAdditionsSep2026` spread at the end of the `opportunities` array,
 * `applyHsoUpdateSep2026(opportunities)` right after the eligibility-cleanup loop, and
 * `!isRemovedBySep2026Review(o.id)` in the `allOpportunities` filter.
 */

export type HsoReviewSep2026 = {
  /** ISO date; null shows "Deadline TBA" when no next-cycle date is published yet. */
  deadline?: string | null;
  /** ISO date the application window opens, where the programme publishes one. */
  opensAt?: string | null;
  /** Replacement link, where the listed one was dead or had moved. */
  url?: string;
  /** Programme ended or is not open to high schoolers - hidden from the catalogue. */
  removed?: boolean;
  /** Official page checked by hand; clears an automated link-check review flag. */
  verified?: boolean;
  /** Corrected title, where the programme was renamed. */
  title?: string;
  /** Corrected description, where the listed one stated something the official page contradicts. */
  blurb?: string;
  /** Corrected category, applied after the automatic category cleanup in opportunities.ts. */
  category?: Opportunity['category'];
  /** Corrected location, where the listed place was the host rather than where a student can take part. */
  location?: string;
  /** Corrected delivery format, where the official page states a different one. */
  format?: Opportunity['format'];
  /** Corrected cost, where the official page shows fees the listing called free, or the reverse. */
  cost?: Opportunity['cost'];
  /** What the official page said, quoted, when it was checked (2026-09-15 to 2026-09-19). */
  evidence: string;
};

