/**
 * The category a DYCD listing should carry, taken from the program type it states.
 *
 * The feed's own "Program type" field is authoritative here, and it is specific:
 * "After-School Programs", "Beacon", "NYCHA Community Center", "Summer Camp",
 * "Jobs & Internships", "Youth Employment". An earlier version of this function
 * only split internships out and swept everything else into "Summer Program",
 * which labelled 359 year-round after-school programmes as summer ones - a student
 * filtering for a summer place got back neighbourhood centres that run during term.
 *
 * Order matters: a site tagged both after-school and employment is an internship
 * first, because that is the part a student applies to.
 */
function dycdCategory(blurb: string): Opportunity["category"] {
  const programType = /Program type:\s*([^.]*)\./.exec(blurb)?.[1] ?? "";
  if (/Jobs & Internships|Youth Employment/.test(programType)) return "Internship";
  if (/Summer Program|Summer Camp/.test(programType)) return "Summer Program";
  // After-school, Beacon, Cornerstone, NYCHA and NDA sites run through the school
  // year. None of the remaining categories fit an ongoing enrichment programme, so
  // they take the same catch-all this catalogue already uses for year-round
  // programmes such as YOLA and the Manhattan School of Music precollege.
  return "Fellowship";
}

export function applyHsoUpdateSep2026(list: Opportunity[]): void {
  for (const opportunity of list) {
    if (opportunity.id.startsWith(DYCD_ID_PREFIX)) opportunity.category = dycdCategory(opportunity.blurb);
    const review = hsoDeadlineReviewSep2026[opportunity.id];
    if (!review) continue;
    if (review.deadline !== undefined) opportunity.deadline = review.deadline;
    if (review.opensAt !== undefined) opportunity.opensAt = review.opensAt;
    if (review.url) opportunity.url = review.url;
    if (review.title) opportunity.title = review.title;
    if (review.blurb) opportunity.blurb = review.blurb;
    if (review.category) opportunity.category = review.category;
    if (review.location) opportunity.location = review.location;
    if (review.format) opportunity.format = review.format;
    if (review.cost) opportunity.cost = review.cost;
    if (review.verified) {
      opportunity.verified = true;
      opportunity.requiresReview = false;
      opportunity.review_note = undefined;
    }
  }
}

/** True for listings this review removed; used by the allOpportunities filter. */
export function isRemovedBySep2026Review(id: string): boolean {
  return (
    hsoDeadlineReviewSep2026[id]?.removed === true ||
    id.startsWith(DEAD_FEED_ID_PREFIX) ||
    DYCD_SERVICE_ROW_IDS.has(id)
  );
}
